import { useMemo } from 'react';
import './Confetti.css';

interface Props {
  count?: number;
}

/**
 * GenAI DECLARATION: The functions in this file (Confetti) were generated by GenAI
 * (ChatGPT) and reviewed, integrated and tested by
 * the team.
 */
export function Confetti({ count = 60 }: Props) {
  const pieces = useMemo(() => {
    const palette = ['#e7b750', '#f6c876', '#f6f2e7', '#c1483c', '#3f9463', '#4b7fa8'];
    return Array.from({ length: count }, (_, i) => ({
      key: i,
      left: Math.random() * 100,
      delay: Math.random() * 0.6,
      duration: 2.4 + Math.random() * 1.8,
      drift: (Math.random() - 0.5) * 180,
      rotation: Math.random() * 720 - 360,
      colour: palette[Math.floor(Math.random() * palette.length)],
      size: 6 + Math.random() * 8,
      shape: Math.random() < 0.5 ? 'rect' : 'circle',
    }));
  }, [count]);

  return (
    <div className="confetti" aria-hidden="true">
      {pieces.map((p) => (
        <span
          key={p.key}
          className={`confetti__piece confetti__piece--${p.shape}`}
          style={{
            left: `${p.left}%`,
            width: `${p.size}px`,
            height: `${p.size * (p.shape === 'rect' ? 1.6 : 1)}px`,
            backgroundColor: p.colour,
            animationDelay: `${p.delay}s`,
            animationDuration: `${p.duration}s`,
            ['--drift' as string]: `${p.drift}px`,
            ['--rot' as string]: `${p.rotation}deg`,
          } as React.CSSProperties}
        />
      ))}
    </div>
  );
}
